import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
import "core-js/modules/es.iterator.map.js";
import request from "@/utils/request";
import config from "@/config/config";
import common from "@/utils/common";
export default {
  name: "DataStatistics",
  mixins: [common],
  data() {
    return {
      boardData: {
        "totalOrder": 0,
        "todayOrder": 0,
        "totalPrice": 0,
        "todayPrice": 0
      },
      boardConfig: [{
        name: '总订单量',
        key: 'totalOrder',
        icon: 'el-icon-s-order',
        color: '#409EFF',
        bgColor: 'rgba(64,158,255,0.1)'
      }, {
        name: '今日订单量',
        key: 'todayOrder',
        icon: 'el-icon-document-checked',
        color: '#67C23A',
        bgColor: 'rgba(103,194,58,0.1)'
      }, {
        name: '总流水',
        key: 'totalPrice',
        icon: 'el-icon-money',
        color: '#E6A23C',
        bgColor: 'rgba(230,162,60,0.1)',
        isMoney: true
      }, {
        name: '今日流水',
        key: 'todayPrice',
        icon: 'el-icon-wallet',
        color: '#F56C6C',
        bgColor: 'rgba(245,108,108,0.1)',
        isMoney: true
      }],
      charts: {
        left: null,
        right: null
      }
    };
  },
  mounted() {
    this.initAllData();
    window.addEventListener('resize', this.handleResize);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.handleResize);
    if (this.charts.left) this.charts.left.dispose();
    if (this.charts.right) this.charts.right.dispose();
  },
  methods: {
    handleResize() {
      this.charts.left && this.charts.left.resize();
      this.charts.right && this.charts.right.resize();
    },
    async initAllData() {
      try {
        const res = await request({
          url: config.backHost + '/echart/boardData'
        });
        if (res.code == 200) {
          res.data.forEach(item => {
            this.boardData[item.type] = item.count;
          });
        }
      } catch (e) {
        console.error(e);
      }
      this.renderHotelTop5();
      this.renderTrendLine();
    },
    async renderHotelTop5() {
      const chartDom = document.getElementById('echartLeft');
      this.charts.left = this.$echarts.init(chartDom);
      try {
        const res = await request({
          url: config.backHost + '/echart/hotelTop5'
        });
        if (res.code == 200) {
          const sortedData = res.data.sort((a, b) => a.orderCount - b.orderCount);
          this.charts.left.setOption({
            tooltip: {
              trigger: 'axis',
              axisPointer: {
                type: 'shadow'
              }
            },
            grid: {
              top: '5%',
              left: '5%',
              right: '8%',
              bottom: '10%',
              containLabel: true
            },
            xAxis: {
              type: 'value',
              splitLine: {
                show: false
              }
            },
            yAxis: {
              type: 'category',
              data: res.data.map(item => item.hotelName),
              axisLabel: {
                color: '#666'
              }
            },
            series: [{
              name: '订单数',
              type: 'bar',
              data: res.data.map(item => item.orderCount),
              barWidth: '40%',
              itemStyle: {
                color: new this.$echarts.graphic.LinearGradient(0, 0, 1, 0, [{
                  offset: 0,
                  color: '#83bff6'
                }, {
                  offset: 1,
                  color: '#188df0'
                }]),
                borderRadius: [0, 5, 5, 0]
              }
            }]
          });
        }
      } catch (e) {
        console.error(e);
      }
    },
    async renderTrendLine() {
      const chartDom = document.getElementById('echartRight');
      this.charts.right = this.$echarts.init(chartDom);
      try {
        const res = await request({
          url: config.backHost + '/echart/recent7Days'
        });
        if (res.code == 200) {
          this.charts.right.setOption({
            tooltip: {
              trigger: 'axis'
            },
            grid: {
              top: '5%',
              left: '5%',
              right: '8%',
              bottom: '10%',
              containLabel: true
            },
            xAxis: {
              type: 'category',
              boundaryGap: false,
              data: res.data.map(item => item.stat_date),
              axisLine: {
                lineStyle: {
                  color: '#EBEEF5'
                }
              }
            },
            yAxis: {
              type: 'value',
              splitLine: {
                lineStyle: {
                  type: 'dashed'
                }
              }
            },
            series: [{
              name: '订单金额',
              type: 'line',
              smooth: true,
              data: res.data.map(item => item.total_amount),
              areaStyle: {
                color: new this.$echarts.graphic.LinearGradient(0, 0, 0, 1, [{
                  offset: 0,
                  color: 'rgba(230,162,60,0.3)'
                }, {
                  offset: 1,
                  color: 'rgba(230,162,60,0)'
                }])
              },
              itemStyle: {
                color: '#E6A23C'
              }
            }]
          });
        }
      } catch (e) {
        console.error(e);
      }
    }
  }
};
